INSERT INTO `feedbacks` (`id`, `remetente_usuario_id`, `remetente_colaborador_id`, `destinatario_usuario_id`, `destinatario_colaborador_id`, `template_id`, `conteudo`, `anonimo`, `presencial`, `anotacoes_internas`, `status`, `created_at`, `updated_at`) VALUES
(11, NULL, 26, NULL, 19, 5, 'Boas ideias de como sacar o cocoli traseiro do guindaste. Parabéns', 1, 0, NULL, 'ativo', '2026-01-29 01:16:20', '2026-01-29 01:16:20'),
(14, 5, NULL, NULL, 34, 7, 'Você tem se desenvolvido bastante ao longo da sua trajetória aqui na Privus. Nesses 3 meses você tem demonstrado capacidade de se adaptar a mudanças, habilidade para resolver problemas e excução das tarefas com agilidade. Busque utilizar a tecnologia a seu favor. Procure ter um gerenciamento de tempo priorizando cada atividade para não se sentir sobrecarregada. Busque estar mais próxima das áreas a fim de ter uma melhor interação do marketing. Colabore com o comercial, tendo uma postura mais ativa com pensamento de venda, enviando informações relevantes para a equipe. Lembre-se, todo aprendizado é importante para o seu crescimento.', 0, 0, NULL, 'ativo', '2026-02-10 13:36:39', '2026-02-10 13:36:39'),
(15, NULL, 26, 10, NULL, 5, 'Ótima profissional, sabe o que fazer e muito paciente,tem ótimas ideias para solucionar problemas, parabéns pelo seu trabalho', 1, 0, NULL, 'ativo', '2026-03-05 10:13:27', '2026-03-05 10:13:27'),
(16, NULL, 26, 8, NULL, 1, 'Parabéns pelo seu trabalho, continue assim esforçado e se dedicando sucesso sempre na sua jornada', 1, 0, NULL, 'ativo', '2026-03-12 11:20:37', '2026-03-12 11:20:37');
