INSERT INTO `openai_prompt_templates` (`id`, `codigo`, `nome`, `descricao`, `categoria`, `prompt_sistema`, `prompt_usuario`, `exemplo`, `ativo`, `ordem`, `vezes_usado`, `created_at`, `updated_at`) VALUES
(1, 'vaga_tecnologia', 'Vaga de Tecnologia', 'Template otimizado para vagas da área de tecnologia e desenvolvimento', 'tecnologia', 'Você é um especialista em recrutamento de tecnologia. Crie vagas detalhadas, técnicas e atrativas para desenvolvedores e profissionais de TI.', 'Crie uma vaga completa de tecnologia baseada na seguinte descrição:\n\n{descricao}\n\nRetorne APENAS um JSON válido com a estrutura especificada.', 'Desenvolvedor Full Stack Python/React para startup de fintech. Remoto, salário 8k-12k, experiência com AWS e Docker', 1, 1, 1, '2026-02-05 16:59:11', '2026-02-05 17:18:19'),
(2, 'vaga_administrativa', 'Vaga Administrativa', 'Template otimizado para vagas administrativas e de escritório', 'administrativo', 'Você é um especialista em recrutamento para áreas administrativas. Crie vagas profissionais e claras para funções de escritório e gestão.', 'Crie uma vaga completa administrativa baseada na seguinte descrição:\n\n{descricao}\n\nRetorne APENAS um JSON válido com a estrutura especificada.', 'Assistente Administrativo para empresa de logística. Presencial em São Paulo, experiência com Excel e atendimento', 1, 2, 2, '2026-02-05 16:59:11', '2026-03-26 12:52:30'),
(3, 'vaga_vendas', 'Vaga de Vendas', 'Template otimizado para vagas comerciais e de vendas', 'vendas', 'Você é um especialista em recrutamento comercial. Crie vagas motivadoras e focadas em resultados para profissionais de vendas.', 'Crie uma vaga completa de vendas baseada na seguinte descrição:\n\n{descricao}\n\nRetorne APENAS um JSON válido com a estrutura especificada.', 'Vendedor Externo para revenda de veículos. Comissão atrativa, carteira própria desejável, experiência em vendas B2C', 1, 3, 2, '2026-02-05 16:59:11', '2026-06-01 18:50:59'),
(4, 'vaga_operacional', 'Vaga Operacional', 'Template otimizado para vagas operacionais e de produção', 'operacional', 'Você é um especialista em recrutamento operacional. Crie vagas claras e objetivas para funções operacionais e de produção.', 'Crie uma vaga completa operacional baseada na seguinte descrição:\n\n{descricao}\n\nRetorne APENAS um JSON válido com a estrutura especificada.', 'Operador de Empilhadeira para centro de distribuição. Turno noturno, CNH B obrigatória, experiência mínima 1 ano', 1, 4, 0, '2026-02-05 16:59:11', '2026-02-05 16:59:11'),
(5, 'vaga_generica', 'Vaga Genérica', 'Template padrão para qualquer tipo de vaga', 'geral', 'Você é um especialista em Recursos Humanos. Crie vagas profissionais, completas e atrativas para candidatos qualificados.', 'Crie uma vaga completa baseada na seguinte descrição:\n\n{descricao}\n\nRetorne APENAS um JSON válido com a estrutura especificada.', 'Gerente de Projetos para empresa de construção civil. Híbrido, experiência com gestão de equipes e prazos', 1, 5, 0, '2026-02-05 16:59:11', '2026-02-05 16:59:11');
