INSERT INTO `reunioes_1on1` (`id`, `lider_id`, `liderado_id`, `data_reuniao`, `hora_inicio`, `hora_fim`, `status`, `assuntos_tratados`, `proximos_passos`, `avaliacao_liderado`, `avaliacao_lider`, `observacoes`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 4, 37, '2025-12-22', '17:15:00', '17:32:00', 'realizada', 'Dias de férias antecipados, como dia 26,29,30,02', 'Ficarão 4 dias uteis em haver para serem pagos em outras datas combinadas previamente, provavelmente em sábados nos meses posteriores, ou caso não aconteça a necessidade, descontado no vencimento das férias.', NULL, NULL, '', 4, '2025-12-22 20:17:07', '2025-12-22 20:17:20'),
(2, 4, 28, '2025-12-19', '10:17:00', '10:30:00', 'realizada', 'Dias trabalhados para compensar férias antecipadas e adiantando outros dias', 'trabalhar nos dias 22, 23, 26, 29, 30 e 02/01 na modalidade home office. \r\nFicando em aberto 8 dias restantes a serem pagos em 2026', NULL, NULL, '', 4, '2025-12-22 20:23:02', '2025-12-22 20:23:24'),
(3, 4, 22, '2025-12-19', '11:17:00', '11:30:00', 'agendada', 'Dias negociados que foram pagos mas não trabalhados, ficando em haver para o periodo do final de ano', 'trabalhar nos dias 22, 23, 26, 29, 30 e 02/01 na modalidade home office para compensar os dias que ficou fora da empresa e retornou, e pela emanda do dayoff do dia do aniversário, combinando assim atender nos dias do recesso citados acima', NULL, NULL, NULL, 4, '2025-12-22 20:25:45', '2025-12-22 20:25:45'),
(4, 53, 28, '2026-03-11', '17:01:00', '17:08:00', 'agendada', 'Dias trabalhados com saldo', 'No final do ano foi feito um trabalho de home office e ficaram 7 dias de saldo, e nos dias 12 e 13 de Março 2026 está sendo retirado 2 dias, ficando restante 5 dias em aberto', NULL, NULL, NULL, 4, '2026-03-11 20:12:18', '2026-03-11 20:12:18');
