INSERT INTO `vagas_geradas_ia` (`id`, `vaga_id`, `usuario_id`, `empresa_id`, `descricao_entrada`, `resposta_ia`, `modelo_usado`, `tokens_usados`, `custo_estimado`, `tempo_geracao_ms`, `campos_editados`, `qualidade_score`, `foi_salva`, `template_usado`, `created_at`) VALUES
(1, NULL, 1, 1, 'designer grafico, modelo pj, 2k de salario', '{\"titulo\":\"Designer Gr\\u00e1fico - PJ\",\"descricao\":\"<p>Estamos em busca de um talentoso Designer Gr\\u00e1fico para se juntar \\u00e0 nossa equipe criativa. Se voc\\u00ea \\u00e9 apaixonado por design, tem um olhar apurado para detalhes e quer contribuir com projetos inovadores, essa \\u00e9 a sua oportunidade. O designer ser\\u00e1 respons\\u00e1vel por criar e desenvolver materiais gr\\u00e1ficos que atendam \\u00e0s necessidades de comunica\\u00e7\\u00e3o visual de nossos clientes e da nossa marca.<\\/p><p>Trabalhar\\u00e1 em um ambiente din\\u00e2mico e colaborativo, onde ter\\u00e1 a chance de aprimorar suas habilidades e crescer profissionalmente. Se voc\\u00ea tem experi\\u00eancia em design gr\\u00e1fico e deseja trabalhar com projetos desafiadores, adorar\\u00edamos conhecer voc\\u00ea!<\\/p>\",\"salario_min\":2000,\"salario_max\":2000,\"tipo_contrato\":\"PJ\",\"beneficios\":[\"Hor\\u00e1rio flex\\u00edvel\",\"Ambiente de trabalho criativo\",\"Oportunidades de desenvolvimento profissional\"],\"requisitos_obrigatorios\":\"<ul><li>Experi\\u00eancia comprovada como Designer Gr\\u00e1fico<\\/li><li>Portf\\u00f3lio de design atualizado<\\/li><li>Dom\\u00ednio das ferramentas Adobe Creative Suite (Photoshop, Illustrator, InDesign)<\\/li><\\/ul>\",\"requisitos_desejaveis\":\"<ul><li>Conhecimento em design de interfaces (UI\\/UX)<\\/li><li>Experi\\u00eancia com anima\\u00e7\\u00f5es e v\\u00eddeos<\\/li><li>Forma\\u00e7\\u00e3o superior em Design Gr\\u00e1fico ou \\u00e1reas relacionadas<\\/li><\\/ul>\",\"competencias_tecnicas\":\"<ul><li>Habilidade em criar layouts atraentes e funcionais<\\/li><li>Conhecimento em teoria das cores e tipografia<\\/li><li>Capacidade de trabalhar com prazos apertados<\\/li><\\/ul>\",\"competencias_comportamentais\":\"<ul><li>Criatividade e inova\\u00e7\\u00e3o<\\/li><li>Boa comunica\\u00e7\\u00e3o e trabalho em equipe<\\/li><li>Proatividade e resolu\\u00e7\\u00e3o de problemas<\\/li><\\/ul>\",\"modalidade\":\"Remoto\",\"localizacao\":null,\"horario_trabalho\":\"09:00 \\u00e0s 18:00\",\"dias_trabalho\":\"Segunda a Sexta\"}', 'gpt-4o', 815, 0.012225, 10593, NULL, 100, 0, 'vaga_tecnologia', '2026-02-05 17:18:19'),
(2, NULL, 4, 3, 'Assistente de marketing, cadastrar e acompanhar marketplaces, desenvolver artes graficas, experiencia em canva, facilidade com computador e IA.\nFaixa salarial de R$2500,00 de segunda a sexta das 8h as 18h', '{\"titulo\":\"Assistente de Marketing\",\"descricao\":\"<p>Estamos em busca de um Assistente de Marketing din\\u00e2mico e criativo para integrar nossa equipe. Este profissional ser\\u00e1 respons\\u00e1vel por cadastrar e acompanhar marketplaces, al\\u00e9m de desenvolver artes gr\\u00e1ficas que destaquem nossa marca e produtos. Valorizamos o conhecimento em ferramentas modernas, por isso, a experi\\u00eancia com Canva e facilidade no uso de tecnologias, incluindo Intelig\\u00eancia Artificial, s\\u00e3o essenciais. O hor\\u00e1rio de trabalho \\u00e9 de segunda a sexta-feira, das 8h \\u00e0s 18h, oferecendo uma oportunidade de crescimento em um ambiente inovador e colaborativo. Junte-se a n\\u00f3s e contribua para o sucesso de nossos projetos de marketing!<\\/p>\",\"salario_min\":2500,\"salario_max\":2500,\"tipo_contrato\":\"CLT\",\"beneficios\":[\"Vale Transporte\",\"Vale Refei\\u00e7\\u00e3o\",\"Plano de Sa\\u00fade\",\"Plano Odontol\\u00f3gico\"],\"requisitos_obrigatorios\":\"<ul><li>Experi\\u00eancia em Canva<\\/li><li>Facilidade com computador e tecnologias de IA<\\/li><li>Habilidade em desenvolver artes gr\\u00e1ficas<\\/li><\\/ul>\",\"requisitos_desejaveis\":\"<ul><li>Experi\\u00eancia pr\\u00e9via em marketplaces<\\/li><li>Conhecimento em estrat\\u00e9gias de marketing digital<\\/li><\\/ul>\",\"competencias_tecnicas\":\"<ul><li>Proficiente em Canva<\\/li><li>Conhecimento b\\u00e1sico de Intelig\\u00eancia Artificial aplicada ao marketing<\\/li><li>Habilidade em design gr\\u00e1fico<\\/li><\\/ul>\",\"competencias_comportamentais\":\"<ul><li>Trabalho em equipe<\\/li><li>Proatividade<\\/li><li>Boa comunica\\u00e7\\u00e3o<\\/li><li>Criatividade<\\/li><\\/ul>\",\"modalidade\":\"Presencial\",\"localizacao\":\"S\\u00e3o Paulo, SP\",\"horario_trabalho\":\"08:00 \\u00e0s 18:00\",\"dias_trabalho\":\"Segunda a Sexta\"}', 'gpt-4o', 806, 0.012090, 6596, NULL, 100, 0, 'vaga_administrativa', '2026-02-10 13:05:32'),
(3, NULL, 4, 1, 'Atendimento de leads e follow up de clientes, consolidação de carteira de clientes na empresa Personizi de vendas de produtos personalizados via e-commerce', '{\"titulo\":\"Consultor de Vendas - Produtos Personalizados\",\"descricao\":\"<p>Venha fazer parte da equipe da Personizi, uma empresa inovadora no mercado de e-commerce especializada em produtos personalizados. Estamos em busca de um Consultor de Vendas din\\u00e2mico e proativo para atender leads, realizar follow-ups e consolidar nossa carteira de clientes. Se voc\\u00ea tem paix\\u00e3o por vendas e deseja crescer em um ambiente estimulante e orientado a resultados, essa oportunidade \\u00e9 para voc\\u00ea!<\\/p><p>Na Personizi, valorizamos o atendimento personalizado e a satisfa\\u00e7\\u00e3o do cliente. Como Consultor de Vendas, voc\\u00ea ser\\u00e1 respons\\u00e1vel por identificar as necessidades dos clientes, oferecer solu\\u00e7\\u00f5es criativas e garantir uma experi\\u00eancia de compra excepcional. Junte-se a n\\u00f3s e fa\\u00e7a a diferen\\u00e7a!<\\/p>\",\"salario_min\":2500,\"salario_max\":4000,\"tipo_contrato\":\"CLT\",\"beneficios\":[\"Vale Refei\\u00e7\\u00e3o\",\"Vale Transporte\",\"Plano de Sa\\u00fade\",\"Seguro de Vida\",\"Comiss\\u00f5es atrativas\"],\"requisitos_obrigatorios\":\"<ul><li>Experi\\u00eancia pr\\u00e9via em vendas<\\/li><li>Excelente comunica\\u00e7\\u00e3o verbal e escrita<\\/li><li>Capacidade de realizar follow-ups eficazes<\\/li><li>Familiaridade com o uso de ferramentas de CRM<\\/li><\\/ul>\",\"requisitos_desejaveis\":\"<ul><li>Experi\\u00eancia no setor de e-commerce<\\/li><li>Conhecimento em produtos personalizados<\\/li><li>Ingl\\u00eas intermedi\\u00e1rio<\\/li><\\/ul>\",\"competencias_tecnicas\":\"<ul><li>Habilidade no uso de plataformas de e-commerce<\\/li><li>Conhecimento em t\\u00e9cnicas de vendas e negocia\\u00e7\\u00e3o<\\/li><li>Capacidade de an\\u00e1lise de mercado<\\/li><\\/ul>\",\"competencias_comportamentais\":\"<ul><li>Proatividade e iniciativa<\\/li><li>Orienta\\u00e7\\u00e3o para resultados<\\/li><li>Empatia e foco no cliente<\\/li><li>Boa gest\\u00e3o do tempo<\\/li><\\/ul>\",\"modalidade\":\"H\\u00edbrido\",\"localizacao\":\"S\\u00e3o Paulo, SP\",\"horario_trabalho\":\"08:00 \\u00e0s 18:00\",\"dias_trabalho\":\"Segunda a Sexta\"}', 'gpt-4o', 850, 0.012750, 6754, NULL, 100, 0, 'vaga_vendas', '2026-02-20 22:02:52'),
(4, NULL, 4, 3, 'Auxiliar adminstrativo para demandas de contas a pagar e receber do Grupo Privus envolvendo as empresas Azzo e Personizi, lançamento de contas, registro em sistemas de gestão e administrativo em geral. Presencial em Poços de Caldas', '{\"titulo\":\"Auxiliar Administrativo - Contas a Pagar e Receber\",\"descricao\":\"<p>O Grupo Privus est\\u00e1 em busca de um Auxiliar Administrativo para se juntar \\u00e0 nossa equipe em Po\\u00e7os de Caldas. Este profissional ser\\u00e1 respons\\u00e1vel por auxiliar nas rotinas de contas a pagar e receber das empresas Azzo e Personizi. As principais atividades incluem o lan\\u00e7amento de contas, registro em sistemas de gest\\u00e3o e tarefas administrativas em geral. Procuramos algu\\u00e9m organizado, detalhista e com vontade de aprender e contribuir para o crescimento das nossas empresas.<\\/p><p>Se voc\\u00ea est\\u00e1 em busca de uma oportunidade de crescimento em um ambiente din\\u00e2mico e colaborativo, esta pode ser a oportunidade ideal para voc\\u00ea.<\\/p>\",\"salario_min\":1800,\"salario_max\":2500,\"tipo_contrato\":\"CLT\",\"beneficios\":[\"Vale Transporte\",\"Vale Refei\\u00e7\\u00e3o\",\"Assist\\u00eancia M\\u00e9dica\",\"Seguro de Vida\"],\"requisitos_obrigatorios\":\"<ul><li>Ensino M\\u00e9dio Completo<\\/li><li>Experi\\u00eancia pr\\u00e9via em rotinas administrativas<\\/li><li>Conhecimento b\\u00e1sico em Excel<\\/li><li>Residir em Po\\u00e7os de Caldas ou regi\\u00e3o<\\/li><\\/ul>\",\"requisitos_desejaveis\":\"<ul><li>Cursando Ensino Superior em Administra\\u00e7\\u00e3o ou \\u00e1reas correlatas<\\/li><li>Experi\\u00eancia com sistemas de gest\\u00e3o financeira<\\/li><li>Conhecimento em concilia\\u00e7\\u00e3o banc\\u00e1ria<\\/li><\\/ul>\",\"competencias_tecnicas\":\"<ul><li>Dom\\u00ednio do Pacote Office<\\/li><li>Conhecimento em sistemas ERP<\\/li><li>Habilidades em organiza\\u00e7\\u00e3o de documentos<\\/li><\\/ul>\",\"competencias_comportamentais\":\"<ul><li>Proatividade<\\/li><li>Boa comunica\\u00e7\\u00e3o<\\/li><li>Trabalho em equipe<\\/li><li>Capacidade de resolu\\u00e7\\u00e3o de problemas<\\/li><\\/ul>\",\"modalidade\":\"Presencial\",\"localizacao\":\"Po\\u00e7os de Caldas, MG\",\"horario_trabalho\":\"08:00 \\u00e0s 17:00\",\"dias_trabalho\":\"Segunda a Sexta\"}', 'gpt-4o', 849, 0.012735, 7320, NULL, 100, 0, 'vaga_administrativa', '2026-03-26 12:52:30'),
(5, NULL, 1, 1, 'Vaga de pós venda, CS e atendimento pós venda ao cliente', '{\"titulo\":\"Especialista em P\\u00f3s-venda e Atendimento ao Cliente\",\"descricao\":\"<p>Estamos em busca de um Especialista em P\\u00f3s-venda e Atendimento ao Cliente que seja apaixonado por garantir a satisfa\\u00e7\\u00e3o e fideliza\\u00e7\\u00e3o de nossos clientes. Voc\\u00ea ser\\u00e1 respons\\u00e1vel por oferecer suporte excepcional, resolver d\\u00favidas e problemas, e garantir que nossos clientes tenham uma experi\\u00eancia positiva e memor\\u00e1vel ap\\u00f3s a compra. Se voc\\u00ea \\u00e9 din\\u00e2mico, proativo e possui habilidades de comunica\\u00e7\\u00e3o excepcionais, queremos conhec\\u00ea-lo!<\\/p><p><strong>Responsabilidades:<\\/strong><\\/p><ul><li>Gerenciar o relacionamento com os clientes ap\\u00f3s a venda, garantindo satisfa\\u00e7\\u00e3o e fidelidade.<\\/li><li>Resolver d\\u00favidas e problemas apresentados pelos clientes de maneira eficiente e eficaz.<\\/li><li>Colaborar com as equipes de vendas e suporte para melhorar continuamente a experi\\u00eancia do cliente.<\\/li><li>Monitorar feedbacks e implementar melhorias nos processos de p\\u00f3s-venda.<\\/li><\\/ul>\",\"salario_min\":3000,\"salario_max\":4500,\"tipo_contrato\":\"CLT\",\"beneficios\":[\"Vale Refei\\u00e7\\u00e3o\",\"Vale Transporte\",\"Plano de Sa\\u00fade\",\"Plano Odontol\\u00f3gico\",\"Seguro de Vida\"],\"requisitos_obrigatorios\":\"<ul><li>Experi\\u00eancia pr\\u00e9via em atendimento ao cliente ou p\\u00f3s-venda.<\\/li><li>Excelentes habilidades de comunica\\u00e7\\u00e3o verbal e escrita.<\\/li><li>Capacidade de resolver problemas de forma r\\u00e1pida e eficiente.<\\/li><li>Conhecimento em ferramentas de CRM.<\\/li><\\/ul>\",\"requisitos_desejaveis\":\"<ul><li>Forma\\u00e7\\u00e3o em Administra\\u00e7\\u00e3o, Marketing ou \\u00e1reas relacionadas.<\\/li><li>Ingl\\u00eas intermedi\\u00e1rio.<\\/li><li>Experi\\u00eancia no setor de tecnologia.<\\/li><\\/ul>\",\"competencias_tecnicas\":\"<ul><li>Conhecimento em CRM e sistemas de gest\\u00e3o de relacionamento com clientes.<\\/li><li>Dom\\u00ednio do pacote Office, especialmente Excel.<\\/li><\\/ul>\",\"competencias_comportamentais\":\"<ul><li>Proatividade e dinamismo.<\\/li><li>Empatia e habilidade para lidar com diferentes perfis de clientes.<\\/li><li>Foco em resultados e satisfa\\u00e7\\u00e3o do cliente.<\\/li><li>Trabalho em equipe e colabora\\u00e7\\u00e3o.<\\/li><\\/ul>\",\"modalidade\":\"H\\u00edbrido\",\"localizacao\":\"S\\u00e3o Paulo, SP\",\"horario_trabalho\":\"08:00 \\u00e0s 18:00\",\"dias_trabalho\":\"Segunda a Sexta\"}', 'gpt-4o', 887, 0.013305, 9351, NULL, 100, 0, 'vaga_vendas', '2026-06-01 18:50:59');
