CREATE TABLE `chat_conversas` (
  `id` int(11) NOT NULL,
  `colaborador_id` int(11) NOT NULL COMMENT 'Colaborador que iniciou a conversa',
  `titulo` varchar(255) DEFAULT NULL COMMENT 'Título da conversa (gerado automaticamente ou manual)',
  `status` enum('nova','aguardando_triagem','em_atendimento','aguardando_colaborador','aguardando_resposta','pendente_informacao','resolvida','fechada','arquivada') DEFAULT 'nova',
  `prioridade` enum('baixa','normal','alta','urgente') DEFAULT 'normal',
  `categoria_id` int(11) DEFAULT NULL COMMENT 'Categoria da conversa',
  `subcategoria` varchar(100) DEFAULT NULL,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Tags para organização' CHECK (json_valid(`tags`)),
  `atribuido_para_usuario_id` int(11) DEFAULT NULL COMMENT 'RH responsável pela conversa',
  `escalado_para_usuario_id` int(11) DEFAULT NULL COMMENT 'Escalado para supervisor',
  `escalado_por_usuario_id` int(11) DEFAULT NULL COMMENT 'Quem escalou',
  `escalado_at` timestamp NULL DEFAULT NULL,
  `motivo_escalacao` text DEFAULT NULL,
  `ultima_mensagem_at` timestamp NULL DEFAULT NULL COMMENT 'Data/hora da última mensagem',
  `ultima_mensagem_por` enum('colaborador','rh') DEFAULT NULL COMMENT 'Quem enviou a última mensagem',
  `total_mensagens` int(11) DEFAULT 0 COMMENT 'Contador de mensagens',
  `total_mensagens_nao_lidas_colaborador` int(11) DEFAULT 0 COMMENT 'Mensagens não lidas pelo colaborador',
  `total_mensagens_nao_lidas_rh` int(11) DEFAULT 0 COMMENT 'Mensagens não lidas pelo RH',
  `colaborador_visualizou_at` timestamp NULL DEFAULT NULL COMMENT 'Última vez que colaborador visualizou',
  `rh_visualizou_at` timestamp NULL DEFAULT NULL COMMENT 'Última vez que RH visualizou',
  `tempo_primeira_resposta_segundos` int(11) DEFAULT NULL COMMENT 'Tempo até primeira resposta do RH',
  `tempo_resolucao_segundos` int(11) DEFAULT NULL COMMENT 'Tempo total até fechamento',
  `tempo_medio_resposta_segundos` int(11) DEFAULT NULL COMMENT 'Média de tempo de resposta do RH',
  `total_respostas_rh` int(11) DEFAULT 0 COMMENT 'Contador de respostas do RH',
  `sla_primeira_resposta_vencimento` timestamp NULL DEFAULT NULL COMMENT 'Quando deve responder pela primeira vez',
  `sla_resolucao_vencimento` timestamp NULL DEFAULT NULL COMMENT 'Quando deve resolver',
  `sla_primeira_resposta_cumprido` tinyint(1) DEFAULT NULL COMMENT 'SLA de primeira resposta foi cumprido',
  `sla_resolucao_cumprido` tinyint(1) DEFAULT NULL COMMENT 'SLA de resolução foi cumprido',
  `sla_alerta_enviado` tinyint(1) DEFAULT 0 COMMENT 'Alerta de SLA próximo de vencer foi enviado',
  `resumo_ia` text DEFAULT NULL COMMENT 'Resumo gerado pela IA',
  `resumo_ia_gerado_at` timestamp NULL DEFAULT NULL COMMENT 'Data/hora do resumo gerado',
  `nota_interna` text DEFAULT NULL COMMENT 'Nota visível apenas para RH',
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Dados adicionais (ex: ocorrência criada, documentos anexados)' CHECK (json_valid(`metadata`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `fechada_at` timestamp NULL DEFAULT NULL COMMENT 'Data/hora de fechamento',
  `fechada_por` int(11) DEFAULT NULL COMMENT 'Usuário que fechou'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

