  `acao` varchar(50) NOT NULL COMMENT 'Tipo de ação (atribuida, fechada, reaberta, escalada, etc)',
  `realizado_por_usuario_id` int(11) DEFAULT NULL COMMENT 'Usuário que realizou a ação',
  `realizado_por_colaborador_id` int(11) DEFAULT NULL COMMENT 'Colaborador que realizou a ação',
  `dados_anteriores` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Estado anterior' CHECK (json_valid(`dados_anteriores`)),
  `dados_novos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Novo estado' CHECK (json_valid(`dados_novos`)),
  `observacoes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

