--
-- Estrutura para tabela `chat_mensagens`
--

CREATE TABLE `chat_mensagens` (
  `id` int(11) NOT NULL,
  `conversa_id` int(11) NOT NULL,
  `enviado_por_usuario_id` int(11) DEFAULT NULL COMMENT 'Usuário RH que enviou (NULL se foi colaborador)',
  `enviado_por_colaborador_id` int(11) DEFAULT NULL COMMENT 'Colaborador que enviou (NULL se foi RH)',
  `tipo` enum('texto','anexo','sistema','acao_rapida','voz') DEFAULT 'texto',
  `mensagem` text DEFAULT NULL COMMENT 'Texto da mensagem',
  `anexo_caminho` varchar(500) DEFAULT NULL COMMENT 'Caminho do arquivo anexado',
  `anexo_nome_original` varchar(255) DEFAULT NULL COMMENT 'Nome original do arquivo',
  `anexo_tipo_mime` varchar(100) DEFAULT NULL COMMENT 'Tipo MIME do arquivo',
  `anexo_tamanho` int(11) DEFAULT NULL COMMENT 'Tamanho em bytes',
  `voz_caminho` varchar(500) DEFAULT NULL COMMENT 'Caminho do arquivo de áudio',
  `voz_duracao_segundos` int(11) DEFAULT NULL COMMENT 'Duração do áudio em segundos',
  `voz_transcricao` text DEFAULT NULL COMMENT 'Transcrição do áudio (opcional, via IA)',
  `acao_rapida_tipo` varchar(50) DEFAULT NULL COMMENT 'Tipo de ação rápida (ex: ocorrencia_criada)',
  `acao_rapida_dados` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Dados da ação rápida' CHECK (json_valid(`acao_rapida_dados`)),
  `lida_por_colaborador` tinyint(1) DEFAULT 0 COMMENT 'Colaborador leu a mensagem',
  `lida_por_rh` tinyint(1) DEFAULT 0 COMMENT 'RH leu a mensagem',
  `lida_por_colaborador_at` timestamp NULL DEFAULT NULL,
  `lida_por_rh_at` timestamp NULL DEFAULT NULL,
  `editada` tinyint(1) DEFAULT 0 COMMENT 'Mensagem foi editada',
  `editada_at` timestamp NULL DEFAULT NULL,
  `editada_por` int(11) DEFAULT NULL,
  `deletada` tinyint(1) DEFAULT 0 COMMENT 'Mensagem foi deletada (soft delete)',
  `deletada_at` timestamp NULL DEFAULT NULL,
  `deletada_por` int(11) DEFAULT NULL,
  `reacoes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Reações à mensagem (emoji, curtidas, etc)' CHECK (json_valid(`reacoes`)),
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Acionadores `chat_mensagens`
--
DELIMITER $$
CREATE TRIGGER `trg_chat_mensagem_insert` AFTER INSERT ON `chat_mensagens` FOR EACH ROW BEGIN
    -- Atualiza contadores da conversa
    UPDATE chat_conversas SET
        total_mensagens = total_mensagens + 1,
        ultima_mensagem_at = NOW(),
        ultima_mensagem_por = IF(NEW.enviado_por_colaborador_id IS NOT NULL, 'colaborador', 'rh'),
        updated_at = NOW()
    WHERE id = NEW.conversa_id;
    
    -- Incrementa contador de não lidas
    IF NEW.enviado_por_colaborador_id IS NOT NULL THEN
        -- Mensagem do colaborador: incrementa não lidas do RH
        UPDATE chat_conversas SET
            total_mensagens_nao_lidas_rh = total_mensagens_nao_lidas_rh + 1,
            status = CASE 
                WHEN status = 'nova' THEN 'aguardando_triagem'
                WHEN status = 'aguardando_colaborador' THEN 'em_atendimento'
                ELSE status
            END
        WHERE id = NEW.conversa_id;
    ELSE
        -- Mensagem do RH: incrementa não lidas do colaborador
        UPDATE chat_conversas SET
            total_mensagens_nao_lidas_colaborador = total_mensagens_nao_lidas_colaborador + 1,
            status = CASE 
                WHEN status IN ('nova', 'aguardando_triagem') THEN 'em_atendimento'
                WHEN status = 'aguardando_resposta' THEN 'em_atendimento'
                ELSE status
            END
        WHERE id = NEW.conversa_id;
        
        -- Calcula tempo de primeira resposta se for primeira mensagem do RH
        UPDATE chat_conversas SET
            tempo_primeira_resposta_segundos = TIMESTAMPDIFF(SECOND, created_at, NOW()),
            total_respostas_rh = total_respostas_rh + 1
        WHERE id = NEW.conversa_id 
        AND total_respostas_rh = 0;
        
        -- Atualiza tempo médio de resposta
        UPDATE chat_conversas SET
            tempo_medio_resposta_segundos = (
                SELECT AVG(TIMESTAMPDIFF(SECOND, m1.created_at, m2.created_at))
                FROM chat_mensagens m1
                INNER JOIN chat_mensagens m2 ON m1.conversa_id = m2.conversa_id
                WHERE m1.conversa_id = NEW.conversa_id
                AND m1.enviado_por_colaborador_id IS NOT NULL
                AND m2.enviado_por_usuario_id IS NOT NULL
                AND m2.created_at > m1.created_at
                AND m2.id = (
                    SELECT MIN(m3.id)
                    FROM chat_mensagens m3
                    WHERE m3.conversa_id = m1.conversa_id
                    AND m3.enviado_por_usuario_id IS NOT NULL
                    AND m3.created_at > m1.created_at
                )
            )
        WHERE id = NEW.conversa_id;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_chat_mensagem_lida` AFTER UPDATE ON `chat_mensagens` FOR EACH ROW BEGIN
    -- Se foi marcada como lida pelo colaborador
    IF OLD.lida_por_colaborador = FALSE AND NEW.lida_por_colaborador = TRUE THEN
        UPDATE chat_conversas SET
            total_mensagens_nao_lidas_colaborador = GREATEST(0, total_mensagens_nao_lidas_colaborador - 1),
            colaborador_visualizou_at = NOW()
        WHERE id = NEW.conversa_id;
    END IF;
    
    -- Se foi marcada como lida pelo RH
    IF OLD.lida_por_rh = FALSE AND NEW.lida_por_rh = TRUE THEN
        UPDATE chat_conversas SET
            total_mensagens_nao_lidas_rh = GREATEST(0, total_mensagens_nao_lidas_rh - 1),
            rh_visualizou_at = NOW()
        WHERE id = NEW.conversa_id;
    END IF;
END
$$
DELIMITER ;

