  `token_confirmacao` varchar(64) DEFAULT NULL COMMENT 'Token único para confirmação via link',
  `presente` tinyint(1) DEFAULT NULL COMMENT 'Se realmente compareceu ao evento',
  `data_confirmacao` datetime DEFAULT NULL COMMENT 'Data/hora da confirmação',
