--
-- Estrutura para tabela `ocorrencias`
--

CREATE TABLE `ocorrencias` (
  `id` int(11) NOT NULL,
  `colaborador_id` int(11) NOT NULL,
  `usuario_id` int(11) NOT NULL,
  `tipo` varchar(100) NOT NULL,
  `tipo_ocorrencia_id` int(11) DEFAULT NULL,
  `tempo_atraso_minutos` int(11) DEFAULT NULL,
  `horario_esperado` time DEFAULT NULL COMMENT 'Horário esperado de entrada/saída (apenas visualização)',
  `horario_real` time DEFAULT NULL COMMENT 'Horário real de entrada/saída (apenas visualização)',
  `tipo_ponto` enum('entrada','almoco','cafe','saida') DEFAULT NULL,
  `severidade` enum('leve','moderada','grave','critica') DEFAULT NULL,
  `status_aprovacao` enum('pendente','aprovada','rejeitada') DEFAULT 'aprovada',
  `aprovado_por` int(11) DEFAULT NULL,
  `data_aprovacao` datetime DEFAULT NULL,
  `observacao_aprovacao` text DEFAULT NULL,
  `valor_desconto` decimal(10,2) DEFAULT NULL,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array de tags' CHECK (json_valid(`tags`)),
  `campos_dinamicos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Valores dos campos dinâmicos' CHECK (json_valid(`campos_dinamicos`)),
  `descricao` longtext DEFAULT NULL,
  `data_ocorrencia` date NOT NULL,
  `hora_ocorrencia` time DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `desconta_banco_horas` tinyint(1) DEFAULT 0 COMMENT 'Se TRUE, desconta do banco de horas ao invés de dinheiro',
  `apenas_informativa` tinyint(1) DEFAULT 0 COMMENT 'Se TRUE, a ocorrência é apenas informativa e não gera desconto nem afeta banco de horas',
  `horas_descontadas` decimal(5,2) DEFAULT NULL COMMENT 'Quantidade de horas descontadas do banco',
  `banco_horas_movimentacao_id` int(11) DEFAULT NULL COMMENT 'ID da movimentação no banco de horas (se aplicável)',
  `considera_dia_inteiro` tinyint(1) DEFAULT 0 COMMENT 'Se TRUE, considera como falta do dia inteiro (8h) ao invés de apenas minutos de atraso'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

