  `tipo_desconto` enum('proporcional','fixo','percentual','total') DEFAULT 'proporcional' COMMENT 'proporcional = divide pelo número de dias úteis, fixo = valor fixo por ocorrência, percentual = % do valor do bônus, total = zera o bônus completamente',
  `valor_desconto` decimal(10,2) DEFAULT NULL COMMENT 'Valor fixo ou percentual (depende do tipo_desconto). NULL = proporcional ao valor do bônus',
  `desconta_apenas_aprovadas` tinyint(1) DEFAULT 1 COMMENT 'Se TRUE, só desconta ocorrências aprovadas',
  `desconta_banco_horas` tinyint(1) DEFAULT 0 COMMENT 'Se TRUE, também desconta ocorrências que descontam do banco de horas',
  `periodo_dias` int(11) DEFAULT NULL COMMENT 'Período em dias para considerar ocorrências (NULL = período do fechamento)',
  `ativo` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `verificar_periodo_anterior` tinyint(1) DEFAULT 0 COMMENT 'Se TRUE, verifica ocorrências no período anterior ao fechamento (ex: mês anterior)',
  `periodo_anterior_meses` int(11) DEFAULT 1 COMMENT 'Quantos meses anteriores verificar (usado quando verificar_periodo_anterior = TRUE)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

