--
-- Estrutura para view `vw_chat_conversas_completo`
--
DROP TABLE IF EXISTS `vw_chat_conversas_completo`;

CREATE ALGORITHM=UNDEFINED DEFINER=`privus_rh`@`%` SQL SECURITY DEFINER VIEW `vw_chat_conversas_completo`  AS SELECT `c`.`id` AS `id`, `c`.`colaborador_id` AS `colaborador_id`, `c`.`titulo` AS `titulo`, `c`.`status` AS `status`, `c`.`prioridade` AS `prioridade`, `c`.`categoria_id` AS `categoria_id`, `c`.`subcategoria` AS `subcategoria`, `c`.`tags` AS `tags`, `c`.`atribuido_para_usuario_id` AS `atribuido_para_usuario_id`, `c`.`escalado_para_usuario_id` AS `escalado_para_usuario_id`, `c`.`escalado_por_usuario_id` AS `escalado_por_usuario_id`, `c`.`escalado_at` AS `escalado_at`, `c`.`motivo_escalacao` AS `motivo_escalacao`, `c`.`ultima_mensagem_at` AS `ultima_mensagem_at`, `c`.`ultima_mensagem_por` AS `ultima_mensagem_por`, `c`.`total_mensagens` AS `total_mensagens`, `c`.`total_mensagens_nao_lidas_colaborador` AS `total_mensagens_nao_lidas_colaborador`, `c`.`total_mensagens_nao_lidas_rh` AS `total_mensagens_nao_lidas_rh`, `c`.`colaborador_visualizou_at` AS `colaborador_visualizou_at`, `c`.`rh_visualizou_at` AS `rh_visualizou_at`, `c`.`tempo_primeira_resposta_segundos` AS `tempo_primeira_resposta_segundos`, `c`.`tempo_resolucao_segundos` AS `tempo_resolucao_segundos`, `c`.`tempo_medio_resposta_segundos` AS `tempo_medio_resposta_segundos`, `c`.`total_respostas_rh` AS `total_respostas_rh`, `c`.`sla_primeira_resposta_vencimento` AS `sla_primeira_resposta_vencimento`, `c`.`sla_resolucao_vencimento` AS `sla_resolucao_vencimento`, `c`.`sla_primeira_resposta_cumprido` AS `sla_primeira_resposta_cumprido`, `c`.`sla_resolucao_cumprido` AS `sla_resolucao_cumprido`, `c`.`sla_alerta_enviado` AS `sla_alerta_enviado`, `c`.`resumo_ia` AS `resumo_ia`, `c`.`resumo_ia_gerado_at` AS `resumo_ia_gerado_at`, `c`.`nota_interna` AS `nota_interna`, `c`.`metadata` AS `metadata`, `c`.`created_at` AS `created_at`, `c`.`updated_at` AS `updated_at`, `c`.`fechada_at` AS `fechada_at`, `c`.`fechada_por` AS `fechada_por`, `col`.`nome_completo` AS `colaborador_nome`, `col`.`foto` AS `colaborador_foto`, `col`.`email_pessoal` AS `colaborador_email`, `col`.`cpf` AS `colaborador_cpf`, `col`.`setor_id` AS `colaborador_setor_id`, `s`.`nome_setor` AS `colaborador_setor_nome`, `u`.`nome` AS `atribuido_para_nome`, `u`.`email` AS `atribuido_para_email`, `u`.`foto` AS `atribuido_para_foto`, `cat`.`nome` AS `categoria_nome`, `cat`.`cor` AS `categoria_cor`, count(distinct `m`.`id`) AS `total_mensagens_real`, max(`m`.`created_at`) AS `ultima_mensagem_real_at`, CASE WHEN `c`.`sla_primeira_resposta_vencimento` is not null AND `c`.`sla_primeira_resposta_vencimento` < current_timestamp() AND `c`.`tempo_primeira_resposta_segundos` is null THEN 'vencido' WHEN `c`.`sla_primeira_resposta_vencimento` is not null AND `c`.`sla_primeira_resposta_vencimento` < current_timestamp() + interval 30 minute AND `c`.`tempo_primeira_resposta_segundos` is null THEN 'proximo_vencer' ELSE 'ok' END AS `status_sla_primeira_resposta`, CASE WHEN `c`.`sla_resolucao_vencimento` is not null AND `c`.`sla_resolucao_vencimento` < current_timestamp() AND `c`.`status` not in ('fechada','resolvida') THEN 'vencido' WHEN `c`.`sla_resolucao_vencimento` is not null AND `c`.`sla_resolucao_vencimento` < current_timestamp() + interval 2 hour AND `c`.`status` not in ('fechada','resolvida') THEN 'proximo_vencer' ELSE 'ok' END AS `status_sla_resolucao` FROM (((((`chat_conversas` `c` join `colaboradores` `col` on(`c`.`colaborador_id` = `col`.`id`)) left join `setores` `s` on(`col`.`setor_id` = `s`.`id`)) left join `usuarios` `u` on(`c`.`atribuido_para_usuario_id` = `u`.`id`)) left join `chat_categorias` `cat` on(`c`.`categoria_id` = `cat`.`id`)) left join `chat_mensagens` `m` on(`c`.`id` = `m`.`conversa_id` and `m`.`deletada` = 0)) GROUP BY `c`.`id` ;

