-- Estrutura para view `vw_chat_estatisticas_rh`
--
DROP TABLE IF EXISTS `vw_chat_estatisticas_rh`;

CREATE ALGORITHM=UNDEFINED DEFINER=`privus_rh`@`%` SQL SECURITY DEFINER VIEW `vw_chat_estatisticas_rh`  AS SELECT `u`.`id` AS `usuario_id`, `u`.`nome` AS `usuario_nome`, `u`.`email` AS `usuario_email`, count(distinct `c`.`id`) AS `total_conversas`, count(distinct case when `c`.`status` = 'nova' then `c`.`id` end) AS `conversas_novas`, count(distinct case when `c`.`status` = 'aguardando_triagem' then `c`.`id` end) AS `conversas_aguardando_triagem`, count(distinct case when `c`.`status` = 'em_atendimento' then `c`.`id` end) AS `conversas_em_atendimento`, count(distinct case when `c`.`status` = 'aguardando_colaborador' then `c`.`id` end) AS `conversas_aguardando_colaborador`, count(distinct case when `c`.`status` = 'fechada' then `c`.`id` end) AS `conversas_fechadas`, count(distinct case when `c`.`total_mensagens_nao_lidas_rh` > 0 then `c`.`id` end) AS `conversas_nao_lidas`, avg(`c`.`tempo_primeira_resposta_segundos`) AS `tempo_medio_primeira_resposta_segundos`, avg(`c`.`tempo_resolucao_segundos`) AS `tempo_medio_resolucao_segundos`, avg(`c`.`tempo_medio_resposta_segundos`) AS `tempo_medio_resposta_segundos`, count(distinct `m`.`id`) AS `total_mensagens_enviadas`, sum(case when `c`.`sla_primeira_resposta_cumprido` = 1 then 1 else 0 end) AS `sla_primeira_resposta_cumprido`, sum(case when `c`.`sla_resolucao_cumprido` = 1 then 1 else 0 end) AS `sla_resolucao_cumprido`, count(distinct case when `c`.`sla_primeira_resposta_cumprido` = 0 then `c`.`id` end) AS `sla_primeira_resposta_nao_cumprido`, count(distinct case when `c`.`sla_resolucao_cumprido` = 0 then `c`.`id` end) AS `sla_resolucao_nao_cumprido` FROM ((`usuarios` `u` left join `chat_conversas` `c` on(`c`.`atribuido_para_usuario_id` = `u`.`id`)) left join `chat_mensagens` `m` on(`m`.`conversa_id` = `c`.`id` and `m`.`enviado_por_usuario_id` = `u`.`id` and `m`.`deletada` = 0)) WHERE `u`.`role` in ('ADMIN','RH') GROUP BY `u`.`id`, `u`.`nome`, `u`.`email` ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_chat_metricas_gerais`
--
DROP TABLE IF EXISTS `vw_chat_metricas_gerais`;

CREATE ALGORITHM=UNDEFINED DEFINER=`privus_rh`@`%` SQL SECURITY DEFINER VIEW `vw_chat_metricas_gerais`  AS SELECT count(distinct `c`.`id`) AS `total_conversas`, count(distinct case when `c`.`status` not in ('fechada','arquivada') then `c`.`id` end) AS `conversas_abertas`, count(distinct case when `c`.`status` = 'nova' then `c`.`id` end) AS `conversas_novas`, count(distinct case when `c`.`status` = 'em_atendimento' then `c`.`id` end) AS `conversas_em_atendimento`, count(distinct case when `c`.`total_mensagens_nao_lidas_rh` > 0 then `c`.`id` end) AS `conversas_nao_lidas_rh`, count(distinct case when `c`.`total_mensagens_nao_lidas_colaborador` > 0 then `c`.`id` end) AS `conversas_nao_lidas_colaborador`, avg(`c`.`tempo_primeira_resposta_segundos`) AS `tempo_medio_primeira_resposta_segundos`, avg(`c`.`tempo_resolucao_segundos`) AS `tempo_medio_resolucao_segundos`, avg(`c`.`tempo_medio_resposta_segundos`) AS `tempo_medio_resposta_segundos`, sum(case when `c`.`sla_primeira_resposta_cumprido` = 1 then 1 else 0 end) AS `sla_primeira_resposta_cumprido`, sum(case when `c`.`sla_resolucao_cumprido` = 1 then 1 else 0 end) AS `sla_resolucao_cumprido`, count(distinct case when `c`.`sla_primeira_resposta_vencimento` < current_timestamp() and `c`.`tempo_primeira_resposta_segundos` is null then `c`.`id` end) AS `sla_vencido_primeira_resposta`, count(distinct case when `c`.`sla_resolucao_vencimento` < current_timestamp() and `c`.`status` not in ('fechada','resolvida') then `c`.`id` end) AS `sla_vencido_resolucao` FROM `chat_conversas` AS `c` ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_flags_estatisticas`
--
DROP TABLE IF EXISTS `vw_flags_estatisticas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`privus_rh`@`%` SQL SECURITY DEFINER VIEW `vw_flags_estatisticas`  AS SELECT `c`.`id` AS `colaborador_id`, `c`.`nome_completo` AS `nome_completo`, count(case when `f`.`status` = 'ativa' then 1 end) AS `flags_ativas`, count(case when `f`.`status` = 'expirada' then 1 end) AS `flags_expiradas`, count(`f`.`id`) AS `total_flags`, max(case when `f`.`status` = 'ativa' then `f`.`data_validade` end) AS `proxima_expiracao`, min(case when `f`.`status` = 'ativa' then `f`.`data_flag` end) AS `primeira_flag_ativa` FROM (`colaboradores` `c` left join `ocorrencias_flags` `f` on(`c`.`id` = `f`.`colaborador_id`)) WHERE `c`.`status` = 'ativo' GROUP BY `c`.`id`, `c`.`nome_completo` ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_loja_estatisticas`
--
DROP TABLE IF EXISTS `vw_loja_estatisticas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`privus_rh`@`%` SQL SECURITY DEFINER VIEW `vw_loja_estatisticas`  AS SELECT (select count(0) from `loja_produtos` where `loja_produtos`.`ativo` = 1) AS `total_produtos_ativos`, (select count(0) from `loja_categorias` where `loja_categorias`.`ativo` = 1) AS `total_categorias_ativas`, (select count(0) from `loja_resgates` where `loja_resgates`.`status` = 'pendente') AS `resgates_pendentes`, (select count(0) from `loja_resgates` where `loja_resgates`.`status` = 'aprovado') AS `resgates_aprovados`, (select count(0) from `loja_resgates` where `loja_resgates`.`status` = 'preparando') AS `resgates_preparando`, (select count(0) from `loja_resgates` where `loja_resgates`.`status` = 'enviado') AS `resgates_enviados`, (select count(0) from `loja_resgates` where `loja_resgates`.`status` = 'entregue') AS `resgates_entregues`, (select count(0) from `loja_resgates` where cast(`loja_resgates`.`created_at` as date) = curdate()) AS `resgates_hoje`, (select coalesce(sum(`loja_resgates`.`pontos_total`),0) from `loja_resgates` where `loja_resgates`.`status` not in ('cancelado','rejeitado') and `loja_resgates`.`forma_pagamento` = 'pontos') AS `pontos_gastos_total`, (select coalesce(sum(`loja_resgates`.`pontos_total`),0) from `loja_resgates` where month(`loja_resgates`.`created_at`) = month(curdate()) and year(`loja_resgates`.`created_at`) = year(curdate()) and `loja_resgates`.`status` not in ('cancelado','rejeitado') and `loja_resgates`.`forma_pagamento` = 'pontos') AS `pontos_gastos_mes`, (select coalesce(sum(`loja_resgates`.`valor_dinheiro`),0) from `loja_resgates` where `loja_resgates`.`status` not in ('cancelado','rejeitado') and `loja_resgates`.`forma_pagamento` = 'dinheiro') AS `dinheiro_gasto_total`, (select coalesce(sum(`loja_resgates`.`valor_dinheiro`),0) from `loja_resgates` where month(`loja_resgates`.`created_at`) = month(curdate()) and year(`loja_resgates`.`created_at`) = year(curdate()) and `loja_resgates`.`status` not in ('cancelado','rejeitado') and `loja_resgates`.`forma_pagamento` = 'dinheiro') AS `dinheiro_gasto_mes` ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_ocorrencias_estatisticas`
--
DROP TABLE IF EXISTS `vw_ocorrencias_estatisticas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`privus_rh`@`%` SQL SECURITY DEFINER VIEW `vw_ocorrencias_estatisticas`  AS SELECT `c`.`id` AS `colaborador_id`, `c`.`nome_completo` AS `nome_completo`, count(`o`.`id`) AS `total_ocorrencias`, sum(case when `o`.`severidade` = 'leve' then 1 else 0 end) AS `ocorrencias_leves`, sum(case when `o`.`severidade` = 'moderada' then 1 else 0 end) AS `ocorrencias_moderadas`, sum(case when `o`.`severidade` = 'grave' then 1 else 0 end) AS `ocorrencias_graves`, sum(case when `o`.`severidade` = 'critica' then 1 else 0 end) AS `ocorrencias_criticas`, sum(case when `o`.`status_aprovacao` = 'pendente' then 1 else 0 end) AS `ocorrencias_pendentes`, count(distinct date_format(`o`.`data_ocorrencia`,'%Y-%m')) AS `meses_com_ocorrencias`, max(`o`.`data_ocorrencia`) AS `ultima_ocorrencia`, count(distinct `a`.`id`) AS `total_advertencias` FROM ((`colaboradores` `c` left join `ocorrencias` `o` on(`c`.`id` = `o`.`colaborador_id`)) left join `ocorrencias_advertencias` `a` on(`c`.`id` = `a`.`colaborador_id`)) WHERE `c`.`status` = 'ativo' GROUP BY `c`.`id`, `c`.`nome_completo` ;

